-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create table public.offers (
  id uuid default gen_random_uuid() not null,
  listing_id uuid not null,
  buyer_id uuid not null,
  amount_cents integer not null,
  status text default 'open'::text not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  counter_amount_cents integer,
  countered_at timestamp with time zone,
  expires_at timestamp with time zone,
  responded_at timestamp with time zone,
  round_count integer default 0 not null,
  last_round_id uuid,
  ended_reason text
);

alter table public.offers enable row level security;

-- Comments
comment on column public.offers.ended_reason is 'N77: why DRVN ended the offer rather than one of its parties. listing_withdrawn: the seller withdrew the listing.';

-- Constraints
alter table public.offers add constraint offers_amount_ceiling CHECK (amount_cents <= 100000000);
alter table public.offers add constraint offers_amount_cents_check CHECK (amount_cents > 0);
alter table public.offers add constraint offers_buyer_id_fkey FOREIGN KEY (buyer_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
alter table public.offers add constraint offers_counter_bounds CHECK (counter_amount_cents IS NULL OR counter_amount_cents > 0 AND counter_amount_cents <= 100000000);
alter table public.offers add constraint offers_ended_reason_check CHECK (ended_reason IS NULL OR ended_reason = 'listing_withdrawn'::text AND status = 'withdrawn'::text);
alter table public.offers add constraint offers_last_round_id_fkey FOREIGN KEY (last_round_id) REFERENCES public.offer_rounds(id) ON DELETE SET NULL;
alter table public.offers add constraint offers_listing_id_fkey FOREIGN KEY (listing_id) REFERENCES public.listings(id) ON DELETE CASCADE;
alter table public.offers add constraint offers_pkey PRIMARY KEY (id);
alter table public.offers add constraint offers_status_check CHECK (status = ANY (ARRAY['open'::text, 'countered'::text, 'accepted'::text, 'declined'::text, 'withdrawn'::text, 'expired'::text]));

-- Indexes
CREATE INDEX offers_buyer_idx ON public.offers USING btree (buyer_id, created_at DESC);
CREATE INDEX offers_last_round_id_idx ON public.offers USING btree (last_round_id) WHERE (last_round_id IS NOT NULL);
CREATE INDEX offers_listing_idx ON public.offers USING btree (listing_id);
CREATE UNIQUE INDEX offers_one_live_buyer_listing ON public.offers USING btree (listing_id, buyer_id) WHERE (status = ANY (ARRAY['open'::text, 'countered'::text]));
CREATE INDEX offers_status_idx ON public.offers USING btree (status) WHERE (status = ANY (ARRAY['open'::text, 'countered'::text]));

-- Grants
grant maintain, select on table public.offers to anon;
